export function hasTechMark(slug?: string): boolean {
  return !!slug && slug in MARKS;
}

/** Renders a brand mark at its own aspect ratio, sized by height. The markup is
 *  build-time constant from devicon and Simple Icons, never user input. */
export function TechMark({ slug, className }: { slug: string; className?: string }) {
  const mark = MARKS[slug];
  if (!mark) return null;
  return (
    <svg
      viewBox={mark.viewBox}
      aria-hidden
      className={className}
      dangerouslySetInnerHTML={{ __html: mark.inner }}
    />
  );
}
